function newGeom(){ return {pos:[],nrm:[],col:[],idx:[],vcount:0}; }
function appendGeom(out,g,m,color){
  var base=out.vcount,n=g.pos.length/3;
  var c0=color?color[0]:1,c1=color?color[1]:1,c2=color?color[2]:1;
  for(var i=0;i<n;i++){
    var x=g.pos[i*3],y=g.pos[i*3+1],z=g.pos[i*3+2];
    out.pos.push(m[0]*x+m[4]*y+m[8]*z+m[12], m[1]*x+m[5]*y+m[9]*z+m[13], m[2]*x+m[6]*y+m[10]*z+m[14]);
    var nx=m[0]*g.nrm[i*3]+m[4]*g.nrm[i*3+1]+m[8]*g.nrm[i*3+2];
    var ny=m[1]*g.nrm[i*3]+m[5]*g.nrm[i*3+1]+m[9]*g.nrm[i*3+2];
    var nz=m[2]*g.nrm[i*3]+m[6]*g.nrm[i*3+1]+m[10]*g.nrm[i*3+2];
    var L=hyp3(nx,ny,nz)||1;
    out.nrm.push(nx/L,ny/L,nz/L);
    out.col.push(g.col[i*3]*c0,g.col[i*3+1]*c1,g.col[i*3+2]*c2);
  }
  for(var k2=0;k2<g.idx.length;k2++) out.idx.push(g.idx[k2]+base);
  out.vcount+=n;
}

function moundH(x,z){
  var r=hyp2(x,z);
  var fade=1-smoothstep(0.35,0.93,r);
  var n=fbm2(x*3.5+1.3,z*3.5-0.7);
  return -0.15 + (0.07*n + 0.02*Math.sin(x*7.0+z*5.0))*fade;
}

