function buildMound(){
  var N=84,R=30,rMax=0.988,pos=[],idx=[],i,j,t;
  function bottomY(r){ return -0.99*Math.sqrt(Math.max(0,1-r*r)); }
  for(i=0;i<=R;i++){
    var r=rMax*i/R;
    for(j=0;j<N;j++){
      t=j/N*Math.PI*2;
      var x=r*Math.cos(t),z=r*Math.sin(t);
      pos.push(x,moundH(x,z),z);
    }
  }
  var OB=(R+1)*N;
  for(i=0;i<=R;i++){
    var rb=rMax*(1-i/R);
    for(j=0;j<N;j++){
      t=j/N*Math.PI*2;
      pos.push(rb*Math.cos(t),bottomY(rb),rb*Math.sin(t));
    }
  }
  for(i=0;i<R;i++) for(j=0;j<N;j++){
    var j2=(j+1)%N;
    var a=i*N+j,b=i*N+j2,c=(i+1)*N+j2,d=(i+1)*N+j;
    idx.push(a,b,d,b,c,d);
    var e=OB+i*N+j,f=OB+i*N+j2,g=OB+(i+1)*N+j2,h=OB+(i+1)*N+j;
    idx.push(e,f,h,f,g,h);
  }
  for(j=0;j<N;j++){
    var jj=(j+1)%N;
    var a2=R*N+j,b2=R*N+jj,c2=OB+jj,d2=OB+j;
    idx.push(a2,b2,c2,a2,c2,d2);
  }
  var nrm=computeNormals(pos,idx,[0,-0.6,0]);
  var col=new Float32Array(pos.length);
  for(var k=0;k<pos.length/3;k++){
    var px=pos[k*3],py=pos[k*3+1],pz=pos[k*3+2];
    var sh=0.93+0.07*Math.sin(px*23.0+pz*17.0);
    var blue=clamp((-py-0.15)*0.35,0,0.28);
    col[k*3]=(0.94-blue*0.28)*sh;
    col[k*3+1]=(0.96-blue*0.12)*sh;
    col[k*3+2]=1.00*sh;
  }
  return {pos:pos,nrm:nrm,col:col,idx:idx};
}

function buildPeak(P){
  var N=72,R=24,pos=[],idx=[],col=[],i,j,t;
  function ridge(t){ return 1 + 0.22*Math.sin(3*t+P.seed) + 0.13*Math.sin(5*t+P.seed*2.3) + 0.07*Math.sin(9*t-P.seed); }
  function height(r,t){
    var u=Math.max(0,1-r/P.R);
    var ab=smoothstep(0.0,0.35,r/P.R);
    var rr=1+(ridge(t)-1)*ab;
    var h=P.H*Math.pow(u,1.25)*rr;
    h+=P.H*0.06*Math.sin(t*11+r*20)*Math.pow(u,0.7)*ab;
    return Math.max(0,h);
  }
  for(i=0;i<=R;i++){
    var r=P.R*i/R;
    for(j=0;j<N;j++){
      t=j/N*Math.PI*2;
      var y=PEAK_Y0+height(r,t);
      pos.push(P.x+r*Math.cos(t),y,P.z+r*Math.sin(t));
    }
  }
  for(i=0;i<R;i++) for(j=0;j<N;j++){
    var j2=(j+1)%N;
    var a=i*N+j,b=i*N+j2,c=(i+1)*N+j2,d=(i+1)*N+j;
    idx.push(a,b,d,b,c,d);
  }
  var baseIdx=pos.length/3;
  pos.push(P.x,PEAK_Y0,P.z);
  for(j=0;j<N;j++){ var jb=(j+1)%N; idx.push(baseIdx,R*N+j,R*N+jb); }
  var nrm=computeNormals(pos,idx,[P.x,PEAK_Y0+P.H*0.35,P.z]);
  var snowY=PEAK_Y0+P.H*P.snow;
  var rock=[0.30,0.28,0.33], snow=[0.95,0.975,1.0];
  for(var k=0;k<pos.length/3;k++){
    var px=pos[k*3],py=pos[k*3+1],pz=pos[k*3+2];
    var band=0.055*Math.sin(px*26.0+pz*19.0)+0.035*Math.sin(px*51.0-pz*37.0);
    var m=smoothstep(snowY-0.085,snowY+0.085,py+band);
    var v=0.88+0.12*Math.sin(px*33.0+pz*29.0+py*11.0);
    col.push((rock[0]*(1-m)+snow[0]*m)*v,(rock[1]*(1-m)+snow[1]*m)*v,(rock[2]*(1-m)+snow[2]*m)*v);
  }
  return {pos:pos,nrm:nrm,col:new Float32Array(col),idx:idx};
}

function toGL(g){
  var o={pos:gl.createBuffer(),nrm:gl.createBuffer(),col:gl.createBuffer(),idx:gl.createBuffer(),count:g.idx.length};
  gl.bindBuffer(gl.ARRAY_BUFFER,o.pos); gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(g.pos),gl.STATIC_DRAW);
  gl.bindBuffer(gl.ARRAY_BUFFER,o.nrm); gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(g.nrm),gl.STATIC_DRAW);
  gl.bindBuffer(gl.ARRAY_BUFFER,o.col); gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(g.col),gl.STATIC_DRAW);
  gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,o.idx); gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,new Uint16Array(g.idx),gl.STATIC_DRAW);
  return o;
}

