function drawGeom(g,mat,nmat,baseColor,emissive){
  gl.uniformMatrix4fv(S.uModel,false,mat);
  gl.uniformMatrix3fv(S.uNormalMat,false,nmat);
  gl.uniform3f(S.uBaseColor,baseColor[0],baseColor[1],baseColor[2]);
  gl.uniform3f(S.uEmissive,emissive?emissive[0]:0,emissive?emissive[1]:0,emissive?emissive[2]:0);
  gl.uniform1f(S.uAlpha,1);
  gl.uniform1f(S.uMode,0);
  bindGeom(g);
  gl.drawElements(gl.TRIANGLES,g.count,gl.UNSIGNED_SHORT,0);
}

var lastT=0,timeSec=0;
function frame(now){
  requestAnimationFrame(frame);
  if(!lastT) lastT=now;
  var dt=(now-lastT)/1000;
  if(dt>0.05) dt=0.05;
  if(dt<0) dt=0;
  lastT=now; timeSec+=dt;

  shake=Math.max(0,shake-dt*0.62);
  if(autoSpin&&pointerCount===0) camTheta+=dt*0.13;

  updateParticles(dt,timeSec);

  var wAmp=shake*shake;
  var wz=wAmp*0.10*Math.sin(timeSec*26.0);
  var wx=wAmp*0.075*Math.sin(timeSec*31.0+1.1);
  m4mul(m4rotZ(wz,wobA),m4rotX(wx,wobB),wobM);
  wobN.set(m3fromM4(wobM));

  var cp=Math.cos(camPhi),sp=Math.sin(camPhi);
