function respawn(i){
  var ix=i*3,x,y,z,l;
  do{
    x=Math.random()*2-1; y=Math.random()*2-1; z=Math.random()*2-1;
    l=hyp3(x,y,z);
  }while(l<1e-3||l>1);
  var rad=0.86*Math.pow(Math.random(),0.3333);
  x=x/l*rad; y=y/l*rad; z=z/l*rad;
  if(y<0.18){
    y=0.18+Math.random()*0.62;
    var sc=Math.min(1,0.88/hyp3(x,y,z));
    x*=sc; y*=sc; z*=sc;
  }
  pPos[ix]=x; pPos[ix+1]=y; pPos[ix+2]=z;
  pVel[ix]=(Math.random()-0.5)*0.06;
  pVel[ix+1]=-0.02-Math.random()*0.05;
  pVel[ix+2]=(Math.random()-0.5)*0.06;
  pPh[i]=Math.random()*Math.PI*2;
}
for(var i0=0;i0<COUNT;i0++) respawn(i0);

var shake=0;
function updateParticles(dt,t){
  var swirl=0.38+shake*6.0;
  var damp=Math.exp(-dt*0.8);
  for(var i=0;i<COUNT;i++){
    var ix=i*3;
    var x=pPos[ix],y=pPos[ix+1],z=pPos[ix+2];
    var vx=pVel[ix],vy=pVel[ix+1],vz=pVel[ix+2];
    vx+=(-z*swirl)*dt; vz+=(x*swirl)*dt; vy-=0.14*dt;
    var ph=pPh[i];
    vx+=Math.sin(t*2.1+ph)*0.13*dt;
    vz+=Math.cos(t*1.7+ph)*0.13*dt;
    vx*=damp; vy*=damp; vz*=damp;
    x+=vx*dt; y+=vy*dt; z+=vz*dt;
    var r=hyp3(x,y,z);
    if(r>0.92){
      var k=0.92/r; x*=k; y*=k; z*=k;
      var nx=x/0.92,ny=y/0.92,nz=z/0.92;
      var vr=vx*nx+vy*ny+vz*nz;
      if(vr>0){ vx-=vr*nx*1.7; vy-=vr*ny*1.7; vz-=vr*nz*1.7; }
    }
    if(y<-0.13 || !isFinite(x) || !isFinite(y) || !isFinite(z)){ respawn(i); continue; }
    pPos[ix]=x; pPos[ix+1]=y; pPos[ix+2]=z;
    pVel[ix]=vx; pVel[ix+1]=vy; pVel[ix+2]=vz;
  }
}
function doShake(){
  shake=1.0;
  for(var i=0;i<COUNT;i++){
    var ix=i*3;
    pVel[ix]+=(Math.random()-0.5)*1.7;
    pVel[ix+1]+=(Math.random()-0.25)*1.1;
    pVel[ix+2]+=(Math.random()-0.5)*1.7;
  }
}

