canvas.addEventListener('pointerdown',function(e){
  if(canvas.setPointerCapture){ try{ canvas.setPointerCapture(e.pointerId); }catch(err){} }
  pointers[e.pointerId]={x:e.clientX,y:e.clientY};
  pointerCount++; moved=0;
  if(pointerCount===1){ dragging=true; lastX=e.clientX; lastY=e.clientY; canvas.classList.add('grabbing'); }
  else if(pointerCount===2){
    var ids=Object.keys(pointers);
    var a=pointers[ids[0]],b=pointers[ids[1]];
    lastPinch=hyp2(a.x-b.x,a.y-b.y);
  }
});
canvas.addEventListener('pointermove',function(e){
  if(!pointers[e.pointerId]) return;
  pointers[e.pointerId]={x:e.clientX,y:e.clientY};
  if(pointerCount===1){
    var dx=e.clientX-lastX,dy=e.clientY-lastY;
    lastX=e.clientX; lastY=e.clientY;
    moved+=Math.abs(dx)+Math.abs(dy);
    camTheta-=dx*0.0065;
    camPhi=clamp(camPhi+dy*0.006,-0.30,1.15);
  }else if(pointerCount>=2){
    var ids2=Object.keys(pointers);
    var a2=pointers[ids2[0]],b2=pointers[ids2[1]];
    var d=hyp2(a2.x-b2.x,a2.y-b2.y);
    if(lastPinch>0&&d>1) camDist=clamp(camDist*(lastPinch/d),2.8,8.0);
    lastPinch=d; moved+=8;
  }
});
function endPointer(e){
  if(!pointers[e.pointerId]) return;
  delete pointers[e.pointerId];
  pointerCount=Math.max(0,pointerCount-1);
  if(pointerCount===0){
    canvas.classList.remove('grabbing');
    if(dragging&&moved<6) doShake();
    dragging=false; lastPinch=0;
  }
}
